using System.ComponentModel;
using ModelContextProtocol.Server;

[McpServerToolType]
public static class ConfigTools
{
    [McpServerTool, Description("Updates a configuration value by key.")]
    public static string UpdateConfig(
        [Description("The configuration key to update")] string key,
        [Description("The new value to set")] string value)
    {
        AppConfigStore.Values[key] = value;
        return $"Configuration '{key}' updated to '{value}'.";
    }

    [McpServerTool, Description("Retrieves a configuration value by key.")]
    public static string GetConfig(
        [Description("The configuration key to look up")] string key)
    {
        return AppConfigStore.Values.TryGetValue(key, out var value)
            ? $"{key} = {value}"
            : $"Key '{key}' not found.";
    }
}

using System.ComponentModel;
using System.Text.Json;
using ModelContextProtocol.Server;

[McpServerResourceType]
public static class ConfigResources
{
    [McpServerResource(UriTemplate = "config://app/settings", Name = "App Settings",
        MimeType = "application/json"),
     Description("Returns the current application configuration as JSON.")]
    public static string GetAllSettings()
    {
        return JsonSerializer.Serialize(AppConfigStore.Values, new JsonSerializerOptions
        {
            WriteIndented = true
        });
    }
}

using System.Collections.Concurrent;

public static class AppConfigStore
{
    public static ConcurrentDictionary<string, string> Values { get; } = new()
    {
        ["environment"] = "production",
        ["log_level"] = "Information",
        ["max_connections"] = "100"
    };
}

